// Vincular conversation_id de ElevenLabs a stringee_calls (solo Stringee = bare digits)
const d = $input.first().json;

// Stringee usa bare digits (sin +), Asterisk usa E.164 (con +)
const isStringee = d.phone && !String(d.phone).startsWith('+');

if (d.country !== 'india' || !isStringee || !d.elevenlabs_call_id) {
  return [{ json: { skip: true, reason: 'no es Stringee o no aplica (country=' + d.country + ', phone_format=' + (String(d.phone).startsWith('+') ? 'E164' : 'bare') + ')' } }];
}

const phoneDigits = String(d.phone).replace(/[^0-9]/g, '');
const last10 = phoneDigits.slice(-10);
const convId = String(d.elevenlabs_call_id).replace(/'/g, "''");

const sql = `UPDATE stringee_calls
  SET conversation_id = '${convId}'
  WHERE RIGHT(phone,10) = '${last10}'
    AND conversation_id IS NULL
    AND answered = 1
  ORDER BY start_time DESC
  LIMIT 1;`;

console.log('🔗 Stringee Conv-ID SQL (webhook):', sql.slice(0, 150));
return [{ json: { sql, phone: d.phone, last10, convId, provider: 'stringee' } }];

// Vincula conversation_id a stringee_calls — consume RAW de ElevenLabs (sin filtro de lead_id)
// Esto es independiente del filtro de Sheet (que descarta calls sin lead_id/sourceSheet)
const convos = $input.all().map(i => i.json);
const results = [];

for (const c of convos) {
  const d = c.data || c;

  const convId = String(d.conversation_id || '');
  if (!convId) continue;

  const dyn = d.conversation_initiation_client_data?.dynamic_variables || {};
  const phone = String(dyn.phone || '').replace(/[^0-9+]/g, '');
  let country = String(dyn.country || '').trim().toLowerCase();
  if (['in'].includes(country)) country = 'india';
  if (['np'].includes(country)) country = 'nepal';
  if (!country) {
    if (phone.startsWith('+977') || phone.startsWith('977')) country = 'nepal';
    else if (phone.startsWith('+91') || phone.startsWith('91')) country = 'india';
  }

  // Stringee = bare digits (sin +), Asterisk = E.164 (con +)
  const isStringee = phone && !phone.startsWith('+');

  if (country !== 'india' || !isStringee || !phone) continue;

  const phoneDigits = phone.replace(/[^0-9]/g, '');
  const last10 = phoneDigits.slice(-10);
  const convIdEscaped = convId.replace(/'/g, "''");

  const sql = `UPDATE stringee_calls
    SET conversation_id = '${convIdEscaped}'
    WHERE RIGHT(phone,10) = '${last10}'
      AND conversation_id IS NULL
      AND answered = 1
    ORDER BY start_time DESC
    LIMIT 1;`;

  results.push({ json: { sql, phone, last10, convId, provider: 'stringee' } });
}

if (results.length) console.log(`🔗 Stringee Conv-ID SQL (polling): ${results.length} filas a vincular`);
return results.length ? results : [{ json: { skip: true, reason: 'ninguna conversación raw es Stringee sin vincular' } }];

const item = $input.first();
const raw = item.json;

// ── 1. Recuperar el body CRUDO si el webhook tiene "Raw Body" activado ──────
// (necesario para verificar la firma HMAC de forma fiable)
let rawStr = '';
try {
  if (item.binary && item.binary.data && item.binary.data.data) {
    rawStr = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  }
} catch (e) { /* sin rawBody, seguimos con el body parseado */ }

let body = raw.body || raw;
if (rawStr) { try { body = JSON.parse(rawStr); } catch (e) {} }

// ── 2. Verificación HMAC (formato ElevenLabs: t=timestamp,v0=firma) ─────────
const crypto = require('crypto');
const secret = 'wsec_98c0a66b3f1df7af8eaf22503381cb78ce648dc63da8eead8ce3dafc7a95b630';
const headers = raw.headers || {};
const sigHeader = String(headers['elevenlabs-signature'] || headers['ElevenLabs-Signature'] || '');
if (sigHeader) {
  const parts = Object.fromEntries(sigHeader.split(',').map(p => p.split('=')));
  const timestamp = parts['t'] || '';
  const receivedSig = parts['v0'] || parts['v1'] || '';
  if (timestamp && Math.abs(Date.now() / 1000 - Number(timestamp)) > 1800) {
    throw new Error('Webhook timestamp demasiado viejo (>30min) — posible replay');
  }
  if (rawStr && receivedSig) {
    const expected = crypto.createHmac('sha256', secret).update(timestamp + '.' + rawStr).digest('hex');
    if (receivedSig !== expected) {
      console.warn('⚠️ HMAC no coincide — procesando igual. esperado=' + expected + ' recibido=' + receivedSig + ' rawLen=' + rawStr.length);
    }
  } else if (receivedSig) {
    console.warn('⚠️ HMAC no verificable sin Raw Body — procesando igual. Activa "Raw Body" en el nodo Webhook.');
  }
}

const d = body.data || body;

const conversationId = String(d.conversation_id || d.conversationId || '');
const callSuccessful = String(d.analysis?.call_successful || d.call_successful || '').toLowerCase();
const summary        = d.analysis?.transcript_summary || d.summary || d.conversation_summary || '';
const durationSecs   = Number(d.metadata?.call_duration_secs || d.duration_secs || 0);
const callEndedBy    = String(d.metadata?.termination_reason || d.call_ended_by || '').toLowerCase();

let transcript = '';
if (Array.isArray(d.transcript)) {
  transcript = d.transcript.map(t => `${t.role === 'agent' ? '🤖' : '👤'} ${t.message || ''}`).join(' | ');
} else {
  transcript = typeof d.transcript === 'string' ? d.transcript : JSON.stringify(d.transcript || '');
}

const dc = d.analysis?.data_collection_results
        || d.analysis?.data_collection
        || d.data_collection_results
        || d.data_collection
        || {};

const interested    = String(dc.user_interest?.value      || '').toLowerCase();
const fullName      = String(dc.full_name?.value           || '').replace(/^=/, '').trim();
const callbackReq   = String(dc.callback_requested?.value  || '').toLowerCase();
const callbackDate  = String(dc.callback_date?.value       || '');
const accountOpened = String(dc.account_requested?.value   || '').toLowerCase();

const dynVars = d.conversation_initiation_client_data?.dynamic_variables
             || d.metadata?.dynamic_variables
             || body.conversation_initiation_client_data?.dynamic_variables
             || {};
const leadId = String(dynVars.lead_id || d.lead_id || body.lead_id || '');
const phone  = String(dynVars.phone   || d.phone   || '').replace(/[^0-9+]/g, '');

function canonicalCountry(rawCountry, rawPhone='') {
  const c = String(rawCountry || '').trim().toLowerCase();
  if (['india','in'].includes(c)) return 'india';
  if (['nepal','np'].includes(c)) return 'nepal';
  if (['slot3'].includes(c)) return 'slot3';
  if (['slot4'].includes(c)) return 'slot4';
  const p = String(rawPhone || '').replace(/[^0-9+]/g,'');
  if (p.startsWith('+977') || p.startsWith('977')) return 'nepal';
  if (p.startsWith('+91') || p.startsWith('91')) return 'india';
  return '';
}
const country = canonicalCountry(dynVars.country || d.country || body.country, phone);
const sourceSheet = String(
  dynVars._source_sheet ||
  ({india:'leads',nepal:'leads nepal',slot3:'leads slot3',slot4:'leads slot4'})[country] ||
  ''
);

const callAttempts = dynVars.call_attempts !== undefined ? Number(dynVars.call_attempts) : undefined;

const isVoicemail =
  callEndedBy.includes('voicemail') ||
  String(summary).toLowerCase().includes('voicemail') ||
  (durationSecs > 0 && durationSecs < 8 && callSuccessful !== 'success');

let status, last_call_status, notes;

if (!conversationId) {
  status = 'FAILED'; last_call_status = 'NO_CONV_ID';
  notes = 'Webhook sin conversation_id';
} else if (durationSecs === 0) {
  status = 'NO_ANSWER'; last_call_status = 'NO_ANSWER';
  notes = 'No contestó (duración 0s) | fin: ' + callEndedBy;
} else if (callSuccessful === 'failure' || callSuccessful === 'failed') {
  status = 'FAILED'; last_call_status = 'FAILED';
  notes = 'Llamada fallida: ' + (callEndedBy || 'sin razón');
} else if (isVoicemail) {
  status = 'VOICEMAIL'; last_call_status = 'VOICEMAIL';
  notes = '📵 Buzón de voz | duración: ' + durationSecs + 's';
} else if (callbackReq === 'true' || callbackReq === 'yes') {
  status = 'SCHEDULED'; last_call_status = 'CALLBACK_REQUESTED';
  notes = '📅 Pidió callback | ' + String(summary).slice(0, 200);
} else {
  status = 'SUCCESSFUL'; last_call_status = 'COMPLETED';
  notes = 'Contestó, conversación completa | ' + String(summary).slice(0, 200);
}

console.log('📞 Post-call | lead:', leadId, '| status:', status, '| dur:', durationSecs + 's', '| conv:', conversationId);

const out = {
  lead_id:              leadId,
  country,
  _source_country: country,
  _source_sheet: sourceSheet,
  phone,
  status,
  last_call_status,
  notes,
  elevenlabs_call_id:   conversationId,
  conversation_summary: String(summary).slice(0, 500),
  full_name:            fullName || null,
  interested:           (interested === 'interested' || interested === 'true' || interested === 'yes') ? 'TRUE' : '',
  callback_requested:   (callbackReq === 'true' || callbackReq === 'yes') ? 'TRUE' : '',
  callback_date:        callbackDate,
  account_opened:       (accountOpened === 'yes' || accountOpened === 'true') ? 'PENDING' : '',
  duration_secs:        durationSecs,
  transcript:           transcript.slice(0, 1000),
  last_call_time:       new Date().toISOString()
};
if (callAttempts !== undefined && !Number.isNaN(callAttempts)) out.call_attempts = callAttempts;
if (!out.full_name) delete out.full_name;
if (!out.callback_date) delete out.callback_date;

return [{ json: out }];

const d=$input.first().json||{};
console.log('⚠️ Post-call skipped safely | lead_id:', d.lead_id || '(missing)', '| country:', d.country || '(unknown)', '| source_sheet:', d._source_sheet || '(missing)', '| conv_id:', d.elevenlabs_call_id || '');
return [{json:{...d,_skipped:true,_skip_reason:!d.lead_id?'missing lead_id':'missing safe country route'}}];

const d = $input.first().json;
console.log('✅ Post-call processed | lead_id:', d.lead_id, '| status:', d.status);
return [{ json: { processed: true, lead_id: d.lead_id, status: d.status } }];

const KEY = 'sk_79048a9776812db4416e5c690d0c047132d565fee7d43acd';

const AGENT_IDS = [
  'agent_5701kramx550e3qs2tm11661b48p',
  'agent_7601m209ntj3fyrbg0dcq6w507yq'
];

const WINDOW_MIN = 20;
const after = Math.floor(Date.now()/1000) - (WINDOW_MIN * 60);
const H = { 'xi-api-key': KEY };
const base = 'https://api.elevenlabs.io/v1/convai/conversations';
const byId = new Map();

for (const agentId of [...new Set(AGENT_IDS.filter(Boolean))]) {
  let cursor = '';
  let page = 0;
  do {
    let url = `${base}?page_size=100&summary_mode=include&call_start_after_unix=${after}&agent_id=${encodeURIComponent(agentId)}`;
    if (cursor) url += `&cursor=${encodeURIComponent(cursor)}`;
    const res = await this.helpers.httpRequest({ method: 'GET', url, headers: H, json: true, timeout: 30000 });
    const convos = res.conversations || [];
    for (const c of convos) { if (c.conversation_id) byId.set(c.conversation_id, c); }
    cursor = res.has_more ? (res.next_cursor || '') : '';
    page++;
    console.log(`📄 ${agentId} página ${page}: +${convos.length} | únicos ${byId.size}`);
  } while (cursor && page < 30);
}

const todas = [...byId.values()];
if (!todas.length) { console.log(`⚠️ Sin conversaciones en los últimos ${WINDOW_MIN} min`); return []; }

const CONCURRENCY = 10;
const out = [];
for (let i = 0; i < todas.length; i += CONCURRENCY) {
  const chunk = todas.slice(i, i + CONCURRENCY);
  const results = await Promise.allSettled(
    chunk.map(c => this.helpers.httpRequest({ method: 'GET', url: `${base}/${c.conversation_id}`, headers: H, json: true, timeout: 20000 }).then(det => ({ json: { ...det, _lista: c } })))
  );
  for (let j = 0; j < results.length; j++) {
    if (results[j].status === 'fulfilled') out.push(results[j].value);
    else console.warn('⚠️ Falló detalle ' + chunk[j].conversation_id + ': ' + results[j].reason?.message);
  }
}
console.log(`✅ ${out.length}/${todas.length} detalles obtenidos`);
return out;

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.processedConvIds)) staticData.processedConvIds = [];
const processedSet = new Set(staticData.processedConvIds);

const convos = $input.all().map(i => i.json);
const out = [];
const newlyProcessed = [];

for (const c of convos) {
  const d = c.data || c;

  const convId   = String(d.conversation_id || '');
  if (convId && processedSet.has(convId)) continue;
  const duration = Number(d.metadata?.call_duration_secs || 0);
  const success  = String(d.analysis?.call_successful || '').toLowerCase();
  const endedBy  = String(d.metadata?.termination_reason || '').toLowerCase();
  const summary  = d.analysis?.transcript_summary || '';
  const startTs  = Number(d.metadata?.start_time_unix_secs || 0);

  const dyn     = d.conversation_initiation_client_data?.dynamic_variables || {};
  const leadId  = String(dyn.lead_id || '').trim();
  const phoneDyn = String(dyn.phone || '').replace(/[^0-9+]/g,'');
  let country = String(dyn.country || '').trim().toLowerCase();
  if (['in'].includes(country)) country = 'india';
  if (['np'].includes(country)) country = 'nepal';
  if (!country) {
    if (phoneDyn.startsWith('+977') || phoneDyn.startsWith('977')) country = 'nepal';
    else if (phoneDyn.startsWith('+91') || phoneDyn.startsWith('91')) country = 'india';
  }
  const sourceSheet = String(
    dyn._source_sheet ||
    ({india:'leads',nepal:'leads nepal',slot3:'leads slot3',slot4:'leads slot4'})[country] ||
    ''
  );
  if (!leadId || leadId === 'TEST-MANUAL-001' || !sourceSheet) continue;

  const dc = d.analysis?.data_collection_results || {};
  const callbackReq = String(dc.callback_requested?.value || '').toLowerCase();
  const fullName    = String(dc.full_name?.value || '').replace(/^=/,'').trim();
  const callbackDt  = String(dc.callback_date?.value || '');

  const isVoicemail =
    endedBy.includes('voicemail') ||
    String(summary).toLowerCase().includes('voicemail') ||
    (duration > 0 && duration < 8 && success !== 'success');

  let status, lastCall, notes;
  if (!convId)                                    { status='FAILED';    lastCall='NO_CONV_ID';         notes='Sin conversation_id'; }
  else if (duration === 0)                        { status='NO_ANSWER'; lastCall='NO_ANSWER';          notes='No contestó | '+endedBy; }
  else if (success==='failure'||success==='failed'){ status='FAILED';   lastCall='FAILED';             notes='Falló: '+endedBy; }
  else if (isVoicemail)                           { status='VOICEMAIL'; lastCall='VOICEMAIL';          notes='📵 Buzón | '+duration+'s'; }
  else if (['true','yes'].includes(callbackReq))  { status='SCHEDULED'; lastCall='CALLBACK_REQUESTED'; notes='📅 Callback | '+String(summary).slice(0,200); }
  else                                            { status='SUCCESSFUL';lastCall='COMPLETED';          notes='Contestó | '+String(summary).slice(0,200); }

  const row = {
    lead_id:              leadId,
    country,
    _source_country: country,
    _source_sheet: sourceSheet,
    status,
    last_call_status:     lastCall,
    notes:                notes.slice(0, 500),
    elevenlabs_call_id:   convId,
    conversation_summary: String(summary).slice(0, 500),
    duration_secs:        duration,
    last_call_time:       startTs ? new Date(startTs*1000).toISOString() : new Date().toISOString()
  };
  if (fullName)    row.full_name    = fullName;
  if (callbackDt)  row.callback_date = callbackDt;

  out.push({ json: row });
  if (convId) newlyProcessed.push(convId);
}

staticData.processedConvIds = [...processedSet, ...newlyProcessed].slice(-3000);

console.log(`🔀 Mapeados para actualizar: ${out.length} leads`);
return out;

// Recibe el resultado clasificado por Parse Post-Call Data4 (webhook) o Mapear para Sheet4 (polling).
// Mapea al contrato de LeadStudio /followups y decide scheduleNextAt.
//
// IMPORTANTE — Asterisk vs Stringee:
// Asterisk ya programa su propio scheduleNextAt de forma síncrona en WF2 (respuesta SIP inmediata).
// Stringee es asíncrono: WF2 no sabe el resultado real hasta que ElevenLabs manda este webhook.
// Por eso: si el teléfono es formato Stringee (dígitos sin '+'), WF9 SÍ programa scheduleNextAt.
// Si es Asterisk (E.164 con '+'), WF9 NO reprograma (ya lo hizo WF2, evita pisar el timer).

const d = $json;

const phone = String(d.phone || '');
const isStringee = phone !== '' && !phone.startsWith('+');

const STATUS_TO_OUTCOME = {
  SUCCESSFUL: 'CONNECTED',
  NO_ANSWER:  'NO_ANSWER',
  FAILED:     'NO_ANSWER',
  VOICEMAIL:  'NO_ANSWER',
  SCHEDULED:  'CALLBACK'
};

const STATUS_TO_CALLSTATUS = {
  SUCCESSFUL: 'ANSWERED',
  NO_ANSWER:  'NO_ANSWER',
  FAILED:     'FAILED',
  VOICEMAIL:  'NO_ANSWER',
  SCHEDULED:  'ANSWERED'
};

const outcome    = STATUS_TO_OUTCOME[d.status]    || 'NO_ANSWER';
const callStatus = STATUS_TO_CALLSTATUS[d.status] || 'FAILED';

function addHours(date, h) { return new Date(date.getTime() + h * 3600 * 1000); }

let scheduleNextAt = null;

if (isStringee) {
  const now = new Date();
  if (d.status === 'NO_ANSWER' || d.status === 'FAILED' || d.status === 'VOICEMAIL') {
    scheduleNextAt = addHours(now, 2).toISOString();
  } else if (d.status === 'SCHEDULED') {
    scheduleNextAt = d.callback_date
      ? new Date(d.callback_date).toISOString()
      : addHours(now, 24).toISOString();
  }
  // SUCCESSFUL -> sin reintento (scheduleNextAt queda null)
}

console.log('🧱 WF9 followup payload | lead:', d.lead_id, '| status:', d.status, '| stringee:', isStringee, '| scheduleNextAt:', scheduleNextAt);

return [{ json: {
  ...d,
  outcome,
  callStatus,
  scheduleNextAt,
  is_stringee: isStringee
}}];

// 🧮 FIX (23/09) — Calcula el status REAL del LEAD (no solo el followup del
// timeline) a partir del resultado real de la llamada que llegó por webhook.
//
// Por qué hace falta: WF9 solo hacía POST /followups (crea la entrada del
// timeline) pero NUNCA hacía PATCH /leads/{id} para actualizar el campo
// `status` del lead. Ese campo es el que usan el GET Queue (?status=
// NOT_CONTACTED) y 'Filtrar Vencidos' para decidir si un lead se vuelve a
// llamar. Sin este PATCH, un lead que atendió y quedó CONTACTED de verdad
// podía seguir circulando indefinidamente (caso real: 31 intentos con 12
// conexiones reales, el status del lead nunca se movía de ATTEMPTING).
//
// Aplica igual para Asterisk y Stringee: este nodo es ahora la única fuente
// de verdad para el status final del lead una vez que se conoce el
// resultado real. WF2 solo debe marcar el estado TRANSITORIO al disparar
// (ATTEMPTING) para sacar al lead de la cola mientras se llama — no debe
// escribir un resultado final inventado (ver fix separado en WF2 Stringee:
// 💾 POST Followup (Stringee)1 desactivado, y WF2 Asterisk: 🏁 PATCH Status
// Final (Asterisk)1 puede quedar desactivado sin problema, este nodo lo
// reemplaza para el status final).
const d = $json; // viene de 🧱 Build Followup Payload (WF9) — incluye scheduleNextAt, outcome, etc.

function addHours(date, h) { return new Date(date.getTime() + h * 3600 * 1000); }
function addBusinessDays(date, days) {
  const result = new Date(date.getTime());
  let added = 0;
  while (added < days) {
    result.setDate(result.getDate() + 1);
    const dow = result.getDay();
    if (dow !== 0 && dow !== 6) added++;
  }
  return result;
}
function safeDate(raw, fallbackDate) {
  if (!raw) return fallbackDate;
  try {
    const dt = new Date(raw);
    if (isNaN(dt.getTime())) return fallbackDate;
    return dt;
  } catch (e) {
    return fallbackDate;
  }
}

// call_attempts viaja en dynamic_variables desde WF2 para AMBOS proveedores.
// Si por algún motivo no llegó (worker no lo propagó), asumimos 1 — preferible
// subestimar el ciclo a trabarlo con un número inventado alto.
const attempts = Number.isFinite(Number(d.call_attempts)) && d.call_attempts !== undefined
  ? Number(d.call_attempts)
  : 1;

let leadStatus, leadNextFollowUpAt = null;

if (d.status === 'SUCCESSFUL') {
  leadStatus = 'CONTACTED';
  leadNextFollowUpAt = null; // conectó de verdad -> sale del ciclo de reintentos
} else if (d.status === 'SCHEDULED') {
  // Pidió callback -> lo tratamos como contactado/engaged, con el próximo
  // contacto en la fecha que pidió (o +24h si no se pudo interpretar la fecha).
  leadStatus = 'CONTACTED';
  leadNextFollowUpAt = safeDate(d.callback_date, addHours(new Date(), 24));
} else if (d.status === 'NO_ANSWER' || d.status === 'FAILED' || d.status === 'VOICEMAIL') {
  // Mismo ciclo de reintentos que usa Asterisk en WF2:
  // intento 1 -> +2h -> intento 2 -> +3h -> intento 3 (fin ciclo) ->
  // ciclo 1 fin -> +2 días hábiles -> ciclo 2 fin -> +3 días hábiles -> ciclo 3 fin -> CLOSED
  const now = new Date();
  const posInCycle = ((attempts - 1) % 3) + 1;
  const cycle = Math.ceil(attempts / 3);

  if (posInCycle === 1) {
    leadStatus = 'NO_ANSWER';
    leadNextFollowUpAt = addHours(now, 2);
  } else if (posInCycle === 2) {
    leadStatus = 'NO_ANSWER';
    leadNextFollowUpAt = addHours(now, 3);
  } else if (cycle === 1) {
    leadStatus = 'NO_ANSWER';
    leadNextFollowUpAt = addBusinessDays(now, 2);
  } else if (cycle === 2) {
    leadStatus = 'NO_ANSWER';
    leadNextFollowUpAt = addBusinessDays(now, 3);
  } else {
    leadStatus = 'CLOSED';
    leadNextFollowUpAt = null;
  }
} else {
  // Defensivo — no debería llegar acá dado el mapeo de STATUS_TO_OUTCOME.
  leadStatus = 'NO_ANSWER';
  leadNextFollowUpAt = addHours(new Date(), 2);
}

const leadNextFollowUpAtIso = leadNextFollowUpAt ? leadNextFollowUpAt.toISOString() : null;

console.log('🧮 WF9 lead patch | lead:', d.lead_id, '| call_status:', d.status, '| attempts:', attempts, '| leadStatus:', leadStatus, '| leadNextFollowUpAt:', leadNextFollowUpAtIso);

return [{ json: {
  ...d,
  leadStatus,
  leadNextFollowUpAt: leadNextFollowUpAtIso,
  leadAttempts: attempts
}}];

